/** Default Open Graph image, generated by `app/opengraph-image.tsx`. */
export const DEFAULT_OG_IMAGE_PATH = '/opengraph-image'

/**
 * The site's public origin. Same source the email links use (`AUTH_URL`, then `NEXTAUTH_URL`),
 * falling back to the production origin. No trailing slash.
 */
export function getSiteUrl(): string {
  const url = process.env.AUTH_URL || process.env.NEXTAUTH_URL || 'https://eatforkful.com'
  return url.replace(/\/+$/, '')
}

/** Absolute URL for a site path; absolute inputs pass through unchanged. */
export function absoluteUrl(path: string): string {
  if (/^https?:\/\//i.test(path)) return path
  return `${getSiteUrl()}${path.startsWith('/') ? path : `/${path}`}`
}

interface JsonLdPost {
  slug: string
  title: string
  description: string
  date: string
  ogImage?: string
}

/** schema.org BlogPosting for a blog post. */
export function blogPostingJsonLd(post: JsonLdPost) {
  return {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: post.title,
    description: post.description,
    ...(post.date ? { datePublished: post.date } : {}),
    author: { '@type': 'Person', name: 'Steve' },
    url: absoluteUrl(`/blog/${post.slug}`),
    image: absoluteUrl(post.ogImage ?? DEFAULT_OG_IMAGE_PATH),
  }
}

/** JSON for a `<script type="application/ld+json">` body; `<` is escaped so content can't close the tag. */
export function serializeJsonLd(data: unknown): string {
  return JSON.stringify(data).replace(/</g, '\\u003c')
}
